      out.write("    'salad':        'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=400&q=80',\n");
      out.write("    'dessert':      'https://images.unsplash.com/photo-1551024601-bec78aea704b?w=400&q=80',\n");
      out.write("    'drink':        'https://images.unsplash.com/photo-1544145945-f90425340c7e?w=400&q=80',\n");
      out.write("    'starter':      'https://images.unsplash.com/photo-1617622141675-d3005b9d5e8a?w=400&q=80',\n");
      out.write("    'mains':        'https://images.unsplash.com/photo-1565557623262-b51c2513a641?w=400&q=80',\n");
      out.write("    'south indian': 'https://images.unsplash.com/photo-1630383249896-424e482df921?w=400&q=80',\n");
      out.write("    'north indian': 'https://images.unsplash.com/photo-1631452180519-c014fe946bc7?w=400&q=80',\n");
      out.write("    'chinese':      'https://images.unsplash.com/photo-1585032226651-759b368d7246?w=400&q=80',\n");
      out.write("    'italian':      'https://images.unsplash.com/photo-1595295333158-4742f28fbd85?w=400&q=80',\n");
      out.write("    'seafood':      'https://images.unsplash.com/photo-1615141982883-c7ad0e69fd62?w=400&q=80',\n");
      out.write("    'sandwich':     'https://images.unsplash.com/photo-1553909489-cd47e0907980?w=400&q=80',\n");
      out.write("    'default':      'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=400&q=80'\n");
      out.write("};\n");
      out.write("\n");
      out.write("const categoryIcons = {\n");
      out.write("    'burger': '🍔', 'pizza': '🍕', 'biryani': '🍛', 'noodles': '🍜',\n");
      out.write("    'salad': '🥗', 'dessert': '🍰', 'desserts': '🍰', 'drink': '🥤', 'drinks': '🥤',\n");
      out.write("    'starter': '🥟', 'starters': '🥟', 'mains': '🍛', 'main': '🍛',\n");
      out.write("    'burgers': '🍔', 'south indian': '🥘', 'north indian': '🍲', 'chinese': '🥡',\n");
      out.write("    'italian': '🍝', 'seafood': '🦐', 'sandwich': '🥪', 'sandwiches': '🥪',\n");
      out.write("    'default': '🍽️'\n");
      out.write("};\n");
      out.write("\n");
      out.write("function hashString(str) {\n");
      out.write("    let hash = 0;\n");
      out.write("    for (let i = 0; i < str.length; i++) {\n");
      out.write("        hash = ((hash << 5) - hash) + str.charCodeAt(i);\n");
      out.write("        hash |= 0;\n");
      out.write("    }\n");
      out.write("    return Math.abs(hash);\n");
      out.write("}\n");
      out.write("\n");
      out.write("function getImage(item) {\n");
      out.write("    if (item.imageUrl && item.imageUrl.startsWith('http')) return item.imageUrl;\n");
      out.write("\n");
      out.write("    const name = (item.name || '').toLowerCase().trim();\n");
      out.write("    if (exactDishImages[name]) return exactDishImages[name];\n");
      out.write("\n");
      out.write("    for (const [key, url] of Object.entries(foodKeywordBank)) {\n");
      out.write("        if (name.includes(key)) return url;\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    const cat = (item.category || '').toLowerCase();\n");
      out.write("    for (const [key, url] of Object.entries(categoryDefaultImages)) {\n");
      out.write("        if (cat.includes(key)) return url;\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    return categoryDefaultImages['default'];\n");
      out.write("}\n");
      out.write("\n");
      out.write("function getIcon(cat) {\n");
      out.write("    if (!cat) return '🍽️';\n");
      out.write("    const c = cat.toLowerCase();\n");
      out.write("    return categoryIcons[c] || categoryIcons[c.replace(/s$/, '')] || '🍽️';\n");
      out.write("}\n");
      out.write("\n");
      out.write("async function loadMenu() {\n");
      out.write("    try {\n");
      out.write("        const res = await fetch(ctx + '/api/v1/menu-items');\n");
      out.write("        if (!res.ok) throw new Error('HTTP ' + res.status);\n");
      out.write("        const result = await res.json();\n");
      out.write("        if (!result.data) throw new Error('No data');\n");
      out.write("        allItems = result.data;\n");
      out.write("        buildCategoryTabs(allItems);\n");
      out.write("        renderMenu(allItems);\n");
      out.write("    } catch (err) {\n");
      out.write("        console.error(\"Failed to load menu\", err);\n");
      out.write("        document.getElementById('menuList').innerHTML =\n");
      out.write("            '<p style=\"color:var(--text-muted);grid-column:1/-1;text-align:center;padding:2rem;\">⚠️ Could not load menu. Please refresh.</p>';\n");
      out.write("    }\n");
      out.write("}\n");
      out.write("\n");
      out.write("function buildCategoryTabs(items) {\n");
      out.write("    const cats = [...new Set(items.map(i => i.category).filter(Boolean))];\n");
      out.write("    const container = document.getElementById('categoryTabs');\n");
      out.write("    cats.forEach(cat => {\n");
      out.write("        const btn = document.createElement('button');\n");
      out.write("        btn.className = 'category-tab';\n");
      out.write("        btn.dataset.cat = cat;\n");
      out.write("        btn.onclick = () => filterByCategory(cat);\n");
      out.write("        btn.innerHTML = getIcon(cat) + ' ' + cat;\n");
      out.write("        container.appendChild(btn);\n");
      out.write("    });\n");
      out.write("}\n");
      out.write("\n");
      out.write("function filterByCategory(cat) {\n");
      out.write("    currentCategory = cat;\n");
      out.write("    document.querySelectorAll('.category-tab').forEach(b =>\n");
      out.write("        b.classList.toggle('active', b.dataset.cat === cat));\n");
      out.write("    const filtered = cat === 'all' ? allItems : allItems.filter(i => i.category === cat);\n");
      out.write("    document.getElementById('sectionEmoji').textContent = cat === 'all' ? '🔥' : getIcon(cat);\n");
      out.write("    document.getElementById('sectionLabel').textContent = cat === 'all' ? 'Explore Delicious Menu' : cat;\n");
      out.write("    renderMenu(filtered);\n");
      out.write("}\n");
      out.write("\n");
      out.write("function renderMenu(items) {\n");
      out.write("    const container = document.getElementById('menuList');\n");
      out.write("    container.innerHTML = '';\n");
      out.write("    if (!items || items.length === 0) {\n");
      out.write("        container.innerHTML = '<p style=\"color:var(--text-muted);grid-column:1/-1;text-align:center;padding:2rem;\">No items in this category.</p>';\n");
      out.write("        return;\n");
      out.write("    }\n");
      out.write("    items.forEach((item, idx) => {\n");
      out.write("        const img = getImage(item);\n");
      out.write("        const fallback = categoryDefaultImages['default'];\n");
      out.write("        const card = document.createElement('div');\n");
      out.write("        card.className = 'menu-card';\n");
      out.write("        card.style.animationDelay = (idx * 0.05) + 's';\n");
      out.write("        card.innerHTML =\n");
      out.write("            '<div class=\"food-image-wrap\">' +\n");
      out.write("                '<img src=\"' + img + '\" alt=\"' + item.name + '\" class=\"food-image\" ' +\n");
      out.write("                    'onerror=\"this.onerror=null;this.src=\\'' + fallback + '\\';\">' +\n");
      out.write("                (item.category ? '<span class=\"category-badge\">' + getIcon(item.category) + ' ' + item.category + '</span>' : '') +\n");
      out.write("            '</div>' +\n");
      out.write("            '<div class=\"menu-card-body\">' +\n");
      out.write("                '<div class=\"menu-card-header\">' +\n");
      out.write("                    '<span class=\"item-name\">' + item.name + '</span>' +\n");
      out.write("                    '<span class=\"item-price\">Rs.' + parseFloat(item.price).toFixed(0) + '</span>' +\n");
      out.write("                '</div>' +\n");
      out.write("                (item.description ? '<p class=\"item-desc\">' + item.description + '</p>' : '') +\n");
      out.write("                '<button onclick=\"addToCart(' + item.id + ', this)\" class=\"btn btn-add\">+ Add to Cart</button>' +\n");
      out.write("            '</div>';\n");
      out.write("        container.appendChild(card);\n");
      out.write("    });\n");
      out.write("}\n");
      out.write("\n");
      out.write("async function addToCart(menuItemId, btn) {\n");
      out.write("    btn.disabled = true;\n");
      out.write("    btn.textContent = 'Adding...';\n");
      out.write("    const formData = new URLSearchParams();\n");
      out.write("    formData.append('menuItemId', menuItemId);\n");
      out.write("    formData.append('quantity', 1);\n");
      out.write("    try {\n");
      out.write("        await fetch(ctx + '/api/v1/cart', { method: 'POST', body: formData });\n");
      out.write("        await loadCart();\n");
      out.write("        btn.textContent = '✓ Added!';\n");
      out.write("        btn.style.background = 'linear-gradient(135deg,#22c55e,#16a34a)';\n");
      out.write("        setTimeout(() => {\n");
      out.write("            btn.disabled = false;\n");
      out.write("            btn.textContent = '+ Add to Cart';\n");
      out.write("            btn.style.background = '';\n");
      out.write("        }, 1500);\n");
      out.write("    } catch (e) {\n");
      out.write("        btn.disabled = false;\n");
      out.write("        btn.textContent = '+ Add to Cart';\n");
      out.write("    }\n");
      out.write("}\n");
      out.write("\n");
      out.write("async function loadCart() {\n");
      out.write("    try {\n");
      out.write("        const res = await fetch(ctx + '/api/v1/cart');\n");
      out.write("        const result = await res.json();\n");
      out.write("        const cartContainer = document.getElementById('cartItems');\n");
      out.write("        const payBtn = document.getElementById('payBtn');\n");
      out.write("        const cartSummary = document.getElementById('cartSummary');\n");
      out.write("        const cartBadge = document.getElementById('cartBadge');\n");
      out.write("        cartContainer.innerHTML = '';\n");
      out.write("\n");
      out.write("        if (!result.data || !result.data.items || result.data.items.length === 0) {\n");
      out.write("            cartContainer.innerHTML =\n");
      out.write("                '<div class=\"empty-cart-msg\">' +\n");
      out.write("                    '<span style=\"font-size:2.5rem;\">🛒</span>' +\n");
      out.write("                    '<p>Your cart is empty</p>' +\n");
      out.write("                    '<small>Add items from the menu</small>' +\n");
      out.write("                '</div>';\n");
      out.write("            cartSummary.style.display = 'none';\n");
      out.write("            payBtn.disabled = true;\n");
      out.write("            cartBadge.style.display = 'none';\n");
      out.write("            cartTotal = 0;\n");
      out.write("            return;\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        let subtotal = 0;\n");
      out.write("        let itemCount = 0;\n");
      out.write("        result.data.items.forEach(item => {\n");
      out.write("            const lineTotal = parseFloat(item.price) * item.quantity;\n");
      out.write("            subtotal += lineTotal;\n");
      out.write("            itemCount += item.quantity;\n");
      out.write("            const div = document.createElement('div');\n");
      out.write("            div.className = 'cart-item';\n");
      out.write("            div.innerHTML =\n");
      out.write("                '<div>' +\n");
      out.write("                    '<strong style=\"display:block;font-size:0.9rem;\">' + item.name + '</strong>' +\n");
      out.write("                    '<span style=\"font-size:0.78rem;color:var(--text-muted);\">' +\n");
      out.write("                        'Rs.' + parseFloat(item.price).toFixed(0) + ' &times; ' + item.quantity +\n");
      out.write("                    '</span>' +\n");
      out.write("                '</div>' +\n");
      out.write("                '<span style=\"font-weight:700;color:var(--primary);\">Rs.' + lineTotal.toFixed(0) + '</span>';\n");
      out.write("            cartContainer.appendChild(div);\n");
      out.write("        });\n");
      out.write("\n");
      out.write("        const tax = subtotal * 0.05;\n");
      out.write("        cartTotal = subtotal + tax;\n");
      out.write("\n");
      out.write("        document.getElementById('cartSubtotal').textContent = 'Rs. ' + subtotal.toFixed(2);\n");
      out.write("        document.getElementById('cartTax').textContent       = 'Rs. ' + tax.toFixed(2);\n");
      out.write("        document.getElementById('cartTotal').textContent     = 'Rs. ' + cartTotal.toFixed(2);\n");
      out.write("        document.getElementById('modalTotal').textContent    = 'Rs. ' + cartTotal.toFixed(2);\n");
      out.write("        document.getElementById('cashAmt').textContent       = 'Rs. ' + cartTotal.toFixed(2);\n");
      out.write("        document.getElementById('upiAmt').textContent        = 'Rs. ' + cartTotal.toFixed(2);\n");
      out.write("\n");
      out.write("        cartBadge.textContent = itemCount;\n");
      out.write("        cartBadge.style.display = 'inline-flex';\n");
      out.write("        cartSummary.style.display = 'block';\n");
      out.write("        payBtn.disabled = false;\n");
      out.write("    } catch (err) {\n");
      out.write("        console.error(\"Failed to load cart\", err);\n");
      out.write("    }\n");
      out.write("}\n");
      out.write("\n");
      out.write("// ===== PAYMENT MODAL =====\n");
      out.write("function openPayment() {\n");
      out.write("    document.getElementById('paymentModal').classList.add('active');\n");
      out.write("    document.getElementById('modalTotal').textContent = 'Rs. ' + cartTotal.toFixed(2);\n");
      out.write("    document.getElementById('cashAmt').textContent    = 'Rs. ' + cartTotal.toFixed(2);\n");
      out.write("    document.getElementById('upiAmt').textContent     = 'Rs. ' + cartTotal.toFixed(2);\n");
      out.write("    selectPayment('cash');\n");
      out.write("}\n");
      out.write("\n");
      out.write("function closePayment() {\n");
      out.write("    document.getElementById('paymentModal').classList.remove('active');\n");
      out.write("}\n");
      out.write("\n");
      out.write("function selectPayment(type) {\n");
      out.write("    selectedPayment = type;\n");
      out.write("    ['cash', 'upi', 'card'].forEach(t => {\n");
      out.write("        const opt = document.getElementById('opt-' + t);\n");
      out.write("        const chk = document.getElementById('check-' + t);\n");
      out.write("        const det = document.getElementById('detail-' + t);\n");
      out.write("        const sel = t === type;\n");
      out.write("        opt.classList.toggle('selected', sel);\n");
      out.write("        chk.style.display = sel ? 'flex' : 'none';\n");
      out.write("        det.style.display = sel ? 'block' : 'none';\n");
      out.write("    });\n");
      out.write("}\n");
      out.write("\n");
      out.write("async function confirmPayment() {\n");
      out.write("    const btn = document.getElementById('confirmPayBtn');\n");
      out.write("    btn.disabled = true;\n");
      out.write("    btn.innerHTML = '<span class=\"spinner-sm\"></span> Processing...';\n");
      out.write("\n");
      out.write("    try {\n");
      out.write("        const res = await fetch(ctx + '/api/v1/orders', { method: 'POST' });\n");
      out.write("        const result = await res.json();\n");
      out.write("        closePayment();\n");
      out.write("\n");
      out.write("        if (result.success) {\n");
      out.write("            const payLabel = {cash:'Cash on Delivery', upi:'UPI', card:'Card Payment'}[selectedPayment];\n");
      out.write("            document.getElementById('successMsg').innerHTML =\n");
      out.write("                'Order <strong>#' + result.data.orderId + '</strong> confirmed!<br>' +\n");
      out.write("                '<small>Payment: ' + payLabel + ' | Total: Rs.' + cartTotal.toFixed(2) + '</small>';\n");
      out.write("            document.getElementById('successOverlay').classList.add('active');\n");
      out.write("            loadCart();\n");
      out.write("        } else {\n");
      out.write("            const msg = document.getElementById('message');\n");
      out.write("            msg.className = 'alert-message alert-error';\n");
      out.write("            msg.textContent = (result.error && result.error.message) || 'Could not place order';\n");
      out.write("        }\n");
      out.write("    } catch (err) {\n");
      out.write("        closePayment();\n");
      out.write("        const msg = document.getElementById('message');\n");
      out.write("        msg.className = 'alert-message alert-error';\n");
      out.write("        msg.textContent = 'Connection failed. Please try again.';\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    btn.disabled = false;\n");
      out.write("    btn.innerHTML = '✅ Confirm &amp; Place Order';\n");
      out.write("}\n");
      out.write("\n");
      out.write("function closeSuccess() {\n");
      out.write("    document.getElementById('successOverlay').classList.remove('active');\n");
      out.write("}\n");
      out.write("\n");
      out.write("async function doLogout() {\n");
      out.write("    try {\n");
      out.write("        await fetch(ctx + '/api/v1/logout', { method: 'POST' });\n");
      out.write("    } catch (e) {\n");
      out.write("        console.error('Logout request failed', e);\n");
      out.write("    }\n");
      out.write("    window.location.href = ctx + '/login.jsp';\n");
      out.write("}\n");
      out.write("\n");
      out.write("function formatCard(input) {\n");
      out.write("    let v = input.value.replace(/\\D/g, '').substring(0, 16);\n");
      out.write("    input.value = (v.match(/.{1,4}/g) || []).join(' ') || v;\n");
      out.write("    const padded = (v + '••••••••••••••••').substring(0, 16).match(/.{1,4}/g);\n");
      out.write("    document.getElementById('cardNumPreview').textContent = padded.join(' ');\n");
      out.write("}\n");
      out.write("\n");
      out.write("function formatExpiry(input) {\n");
      out.write("    let v = input.value.replace(/\\D/g, '').substring(0, 4);\n");
      out.write("    if (v.length >= 2) v = v.substring(0,2) + '/' + v.substring(2);\n");
      out.write("    input.value = v;\n");
      out.write("    document.getElementById('cardExpPreview').textContent = v || 'MM/YY';\n");
      out.write("}\n");
      out.write("\n");
      out.write("document.getElementById('paymentModal').addEventListener('click', function(e) {\n");
      out.write("    if (e.target === this) closePayment();\n");
      out.write("});\n");
      out.write("\n");
      out.write("setTimeout(function() {\n");
      out.write("    const toast = document.getElementById('welcomeToast');\n");
      out.write("    if (toast) {\n");
      out.write("        toast.classList.add('hide');\n");
      out.write("        setTimeout(() => toast.remove(), 450);\n");
      out.write("    }\n");
      out.write("}, 4000);\n");
      out.write("\n");
      out.write("function toggleChat() {\n");
      out.write("    document.getElementById('chatPanel').classList.toggle('open');\n");
      out.write("}\n");
      out.write("\n");
      out.write("async function sendChatMessage() {\n");
      out.write("    const input = document.getElementById('chatInput');\n");
      out.write("    const message = input.value.trim();\n");
      out.write("    if (!message) return;\n");
      out.write("\n");
      out.write("    const messagesDiv = document.getElementById('chatMessages');\n");
      out.write("\n");
      out.write("    const userMsg = document.createElement('div');\n");
      out.write("    userMsg.className = 'chat-msg user';\n");
      out.write("    userMsg.textContent = message;\n");
      out.write("    messagesDiv.appendChild(userMsg);\n");
      out.write("\n");
      out.write("    input.value = '';\n");
      out.write("    messagesDiv.scrollTop = messagesDiv.scrollHeight;\n");
      out.write("\n");
      out.write("    const typingMsg = document.createElement('div');\n");
      out.write("    typingMsg.className = 'chat-msg bot';\n");
      out.write("    typingMsg.textContent = '...';\n");
      out.write("    messagesDiv.appendChild(typingMsg);\n");
      out.write("    messagesDiv.scrollTop = messagesDiv.scrollHeight;\n");
      out.write("\n");
      out.write("    try {\n");
      out.write("        const formData = new URLSearchParams();\n");
      out.write("        formData.append('message', message);\n");
      out.write("        const res = await fetch(ctx + '/api/chat', { method: 'POST', body: formData });\n");
      out.write("        const result = await res.json();\n");
      out.write("        typingMsg.remove();\n");
      out.write("        \n");
      out.write("        const botMsg = document.createElement('div');\n");
      out.write("        botMsg.className = 'chat-msg bot';\n");
      out.write("        const replyText = result.reply || (result.data ? result.data.reply : null) || (result.error ? result.error.message : \"I'm here to help with menu, orders, and restaurant questions!\");\n");
      out.write("        botMsg.textContent = replyText;\n");
      out.write("        messagesDiv.appendChild(botMsg);\n");
      out.write("        messagesDiv.scrollTop = messagesDiv.scrollHeight;\n");
      out.write("\n");
      out.write("        // Auto refresh menu or cart if AI executed a live DB command\n");
      out.write("        if (replyText.includes('Live DB Confirmed') || replyText.includes('price') || replyText.includes('stock')) {\n");
      out.write("            loadMenu();\n");
      out.write("        }\n");
      out.write("        if (replyText.includes('cart') || replyText.includes('Cart')) {\n");
      out.write("            loadCart();\n");
      out.write("        }\n");
      out.write("    } catch (e) {\n");
      out.write("        typingMsg.remove();\n");
      out.write("        const errMsg = document.createElement('div');\n");
      out.write("        errMsg.className = 'chat-msg bot';\n");
      out.write("        errMsg.textContent = 'Error contacting assistant.';\n");
      out.write("        messagesDiv.appendChild(errMsg);\n");
      out.write("        messagesDiv.scrollTop = messagesDiv.scrollHeight;\n");
      out.write("    }\n");
      out.write("}\n");
      out.write("\n");
      out.write("window.onload = function() {\n");
      out.write("    loadMenu();\n");
      out.write("    loadCart();\n");
      out.write("};\n");
      out.write("</script>\n");
      out.write("</body>\n");
      out.write("</html>");
